/* The House Edit — no build system required. Online collaboration needs config.js + schema.sql. */
(() => {
  'use strict';
  const $ = id => document.getElementById(id);
  const esc = val => String(val ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const uuid = () => crypto.randomUUID ? crypto.randomUUID() : `id_${Date.now()}_${Math.random().toString(36).slice(2)}`;
  const cleanUrl = value => { try { const url = new URL(String(value||'')); return ['https:','http:'].includes(url.protocol) ? url.href : ''; } catch { return ''; } };
  const safeImageUrl = val => /^data:image\/(?:png|jpeg|webp);base64,[a-z0-9+/=]+$/i.test(String(val||'')) ? String(val) : cleanUrl(val);
  const money = n => n===null||n===undefined||n==='' ? '' : new Intl.NumberFormat('en-AU',{style:'currency',currency:'AUD',maximumFractionDigits:2}).format(Number(n));
  const timeAgo = dt => { const min = Math.round((Date.now()-new Date(dt).getTime())/60000); if(min<2)return 'just now';if(min<60)return `${min}m ago`;if(min<1440)return `${Math.round(min/60)}h ago`;return new Date(dt).toLocaleDateString('en-AU',{day:'numeric',month:'short'}); };
  const ROOMS=[['Kitchen','🍽️'],['Bathroom','🛁'],['Living Room','🛋️'],['Bedroom','🛏️'],['Laundry','🧺'],['Outdoor','🌿'],['Whole House','🏠']];
  const initials = name => String(name||'?').split(' ').slice(0,2).map(x=>x[0]).join('').toUpperCase();
  const color = role => ({owner:'#415b45',partner:'#aa8060',designer:'#73859a'})[role]||'#72816c';
  const roleTitle = role => ({owner:'Homeowner',partner:'Homeowner',designer:'Designer friend'})[role]||'Guest';
  const VOTE_TEXT={love:'♥ Love it',maybe:'◒ Maybe',pass:'✕ Pass'};
  const DEMO_KEY='the-house-edit-demo-v1';
  const cfg=window.HOUSE_EDIT_CONFIG||{};
  const cloudConfigured=Boolean(cfg.supabaseUrl&&cfg.supabasePublishableKey);
  let client=null, mode='demo', state=null, user=null, route={page:'home',room:'all',decision:null,filter:'all',search:''}, channel=null, refreshTimer=null, busy=false, toastTimer=null;

  function makeDemo() {
    const now=new Date().toISOString();
    const members=[{user_id:'me',role:'owner',display_name:'You',project_id:'demo'},{user_id:'partner',role:'partner',display_name:'Your wife',project_id:'demo'},{user_id:'designer',role:'designer',display_name:'Designer friend',project_id:'demo'}];
    const rooms=ROOMS.map(([name,emoji],i)=>({id:'room'+i,project_id:'demo',name,emoji,sort_order:i}));
    const decisions=[
      {id:'d1',project_id:'demo',room_id:'room0',title:'Kitchen splashback tiles',notes:'A feature tile that works with warm cabinetry and the spotted-gum benchtop.',status:'open',winner_option_id:null,created_at:now},
      {id:'d2',project_id:'demo',room_id:'room0',title:'Kitchen tapware finish',notes:'Choose the metal finish we want to carry into other rooms.',status:'open',winner_option_id:null,created_at:now},
      {id:'d3',project_id:'demo',room_id:'room0',title:'Kitchen cabinet colour',notes:'A warm neutral to complement our timber floors.',status:'approved',winner_option_id:'o5',created_at:now},
      {id:'d4',project_id:'demo',room_id:'room1',title:'Bathroom feature tiles',notes:'Compare pattern, finish and grout combinations.',status:'open',winner_option_id:null,created_at:now},
      {id:'d5',project_id:'demo',room_id:'room2',title:'Living room accent palette',notes:'Decide on the accent colour to tie cushions and soft furnishings together.',status:'open',winner_option_id:null,created_at:now},
      {id:'d6',project_id:'demo',room_id:'room0',title:'Pendant lights',notes:'Over the peninsula / breakfast bar.',status:'open',winner_option_id:null,created_at:now}
    ];
    const seeds=[
      ['o1','d1','Blue & gold azulejo','visual-tile-bluegold',null,'Classic Portuguese pattern with warm golden accents.'],
      ['o2','d1','Blue & white azulejo','visual-tile-bluewhite',null,'A cooler, more restrained patterned tile.'],
      ['o3','d2','Brushed brass','visual-brass',null,'Warm metal finish with traditional detailing.'],
      ['o4','d2','Brushed nickel','visual-nickel',null,'Subtle metal finish with a softer silvery tone.'],
      ['o5','d3','Dulux Hog Bristle Quarter','visual-cream',null,'Warm cream cabinetry colour.'],
      ['o6','d3','Muted olive cabinetry','visual-olive',null,'Earthy green alternative.'],
      ['o7','d4','Terracotta square tile','visual-terracotta',null,'Warm, handmade-inspired texture.'],
      ['o8','d4','Blue patterned tile','visual-tile-bluewhite',null,'Traditional patterned feature.'],
      ['o9','d5','Muted olive','visual-olive',null,'Calm natural colour for cushions and upholstery.'],
      ['o10','d5','Soft terracotta','visual-terracotta',null,'Warm and earthy accent.'],
      ['o11','d6','Clear ribbed glass','visual-light',null,'Traditional glass pendant with a delicate texture.']
    ];
    const options=seeds.map(([id,decision_id,title,visual,price,notes])=>({id,decision_id,title,visual,price,notes,image_url:'',image_path:'',source_url:'',created_at:now,created_by:'me'}));
    const votes=[['o1','me','love'],['o1','partner','maybe'],['o1','designer','love'],['o2','me','maybe'],['o2','partner','love'],['o3','me','love'],['o3','partner','love'],['o3','designer','maybe'],['o5','me','love'],['o5','partner','love'],['o5','designer','love'],['o9','partner','love']].map(([option_id,user_id,choice])=>({option_id,user_id,choice}));
    return {project:{id:'demo',name:'Our Home'},members,rooms,decisions,options,votes,comments:[{id:'c1',option_id:'o1',user_id:'designer',body:'Love the warmth this adds against the timber!',created_at:now}],invites:[]};
  }
  function demoSave(){ if(mode==='demo')try {localStorage.setItem(DEMO_KEY,JSON.stringify(state));}catch {toast('Local storage is full; use smaller images.');} }
  function demoPersona(){return localStorage.getItem('the-house-edit-persona')||'me'}
  function initDemo(){mode='demo';try {state=JSON.parse(localStorage.getItem(DEMO_KEY)||'null')||makeDemo();}catch{state=makeDemo();}const id=demoPersona();user={id,role:state.members.find(m=>m.user_id===id)?.role||'owner',email:''};render();}
  function resetDemo(){if(!confirm('Reset the sample project and remove local demo changes?'))return;localStorage.removeItem(DEMO_KEY);initDemo();toast('Demo reset');}
  function roomOf(dec){return state.rooms.find(r=>r.id===dec.room_id)}
  function optionOf(dec){return state.options.filter(o=>o.decision_id===dec.id)}
  function memberOf(uid){return state.members.find(m=>m.user_id===uid)||{user_id:uid,display_name:'Former member',role:'guest'}}
  function getVote(optionId,uid){return state.votes.find(v=>v.option_id===optionId&&v.user_id===uid)?.choice||null}
  function homeowners(){return state.members.filter(m=>['owner','partner'].includes(m.role))}
  function optionAgreement(opt){const hs=homeowners();return hs.length===2&&hs.every(h=>['love','maybe'].includes(getVote(opt.id,h.user_id)))}
  function optionDisagree(opt){const hs=homeowners();return hs.length===2&&hs.some(h=>getVote(opt.id,h.user_id)==='pass')&&hs.some(h=>getVote(opt.id,h.user_id)==='love')}
  function needsMyVote(dec){return dec.status==='open'&&optionOf(dec).length>0&&!optionOf(dec).some(o=>getVote(o.id,user.id));}
  function approvedDecisions(){return state.decisions.filter(d=>d.status!=='open'&&d.winner_option_id)}
  function totalKnownPrice(){return approvedDecisions().reduce((sum,d)=>sum+(Number(state.options.find(o=>o.id===d.winner_option_id)?.price)||0),0)}
  function roomIcon(room){return room.emoji||ROOMS.find(r=>r[0].toLowerCase()===room.name.toLowerCase())?.[1]||'🏡'}
  function roomClass(room){const n=room.name.toLowerCase();return n.includes('kitchen')?'room-kitchen':n.includes('bath')?'room-bathroom':n.includes('living')?'room-living':n.includes('bed')?'room-bedroom':n.includes('laundry')?'room-laundry':n.includes('outdoor')?'room-outdoor':'room-other'}
  // Product images can be rejected by retailer hotlink protection. Try the image
  // cache first, then the original, then Microlink's image delivery endpoint.
  // Each candidate is attempted at most once; old saved items benefit too.
  function photoCandidates(imageUrl, sourceUrl){
    const image=safeImageUrl(imageUrl), source=normalizeSource(sourceUrl);
    if(!image)return [];
    if(image.startsWith('data:'))return [image];
    const relay='https://wsrv.nl/?url='+encodeURIComponent(image)+'&w=1200&output=webp';
    const embedded=source && !isImageLink(source) ? 'https://api.microlink.io?url='+encodeURIComponent(source)+'&embed=image.url' : '';
    return [...new Set(source?[relay,image,embedded].filter(Boolean):[image,relay])];
  }
  function photoTag(url,source,alt,extra='',privateAsset=false){
    const candidates=privateAsset?[safeImageUrl(url)].filter(Boolean):photoCandidates(url,source);
    if(!candidates.length)return '';
    return `<img src="${esc(candidates[0])}" data-image-fallbacks="${esc(JSON.stringify(candidates.slice(1)))}" ${extra} alt="${esc(alt)}" loading="lazy" referrerpolicy="no-referrer">`;
  }
  function imageMarkup(opt, cls='sample'){
    const url=safeImageUrl(opt.display_url||opt.image_url);
    const image=photoTag(url,opt.image_path?'':opt.source_url,opt.title,'',Boolean(opt.image_path));
    const fallback=opt.visual||'visual-blank';
    return `<div class="${cls} ${esc(fallback)}">${image}<div class="${cls==='sample'?'sample-icon':'img-fallback'}" ${image?'style="display:none"':''}>✳</div></div>`;
  }

  function voteDots(dec){const optIds=new Set(optionOf(dec).map(o=>o.id));return `<div style="display:flex" title="People who have voted">${state.members.map(m=>{const voted=state.votes.some(v=>v.user_id===m.user_id&&optIds.has(v.option_id));return `<span class="vote-dot ${voted?'':'missing'}" style="${voted?'background:'+color(m.role):''}" title="${esc(m.display_name)}${voted?' voted':' has not voted'}">${voted?esc(initials(m.display_name)):'?'}</span>`}).join('')}</div>`}
  function statusPill(dec){const v=dec.status||'open';return `<span class="tag ${esc(v)}">${{open:'Under review',approved:'Approved',ordered:'Ordered',installed:'Installed'}[v]||esc(v)}</span>`}
  function header(){return `<header class="topline"><div class="breadcrumbs">${esc(state.project.name)} <span style="color:#c2c8bc"> / </span> ${route.page==='decision'?'Making a selection':route.page==='home'?'Overview':route.page==='selections'?'Final selections':route.page==='people'?'The team':'Decisions'}</div><div class="top-actions">${mode==='demo'?'<span class="pill demo">◌ Demo · this browser only</span>':'<span class="pill">● Shared project</span>'}<button class="btn sm" data-action="refresh">↻ <span class="hide-small">Refresh</span></button></div></header>`}
  function sideNav(){return `<aside class="sidebar"><div class="logo"><span class="logo-emblem">✳</span><span>the house edit<i>.</i></span></div><div class="sidebar-section">Your home</div>${nav('home','⌂','Overview')}${nav('decisions','▦','Design decisions')}${nav('selections','✓','Final selections')}${nav('people','♙','Your people')}<div class="sidebar-section">Rooms</div>${state.rooms.map(r=>`<button class="nav ${(route.page==='decisions'&&route.room===r.id)?'active':''}" data-action="room" data-id="${esc(r.id)}"><span class="nav-icon">${roomIcon(r)}</span>${esc(r.name)}<span class="nav-count">${state.decisions.filter(d=>d.room_id===r.id).length}</span></button>`).join('')}<div class="sidebar-bottom"><div class="profile"><span class="avatar" style="background:${color(user.role)}">${esc(initials(memberOf(user.id).display_name))}</span><div><strong>${esc(memberOf(user.id).display_name)}</strong><small>${roleTitle(user.role)}</small></div></div>${mode==='demo'?`<select class="demo-switch" id="demo-persona" aria-label="Preview as a team member">${state.members.map(m=>`<option value="${esc(m.user_id)}" ${m.user_id===user.id?'selected':''}>Preview as: ${esc(m.display_name)}</option>`).join('')}</select><button class="btn ghost sm" data-action="reset-demo">Reset demo ↺</button>`:`<button class="btn ghost sm" data-action="signout" style="margin-top:11px">Sign out</button>`}</div></aside>`}
  function nav(page,icon,label){return `<button class="nav ${route.page===page?'active':''}" data-action="nav" data-page="${page}"><span class="nav-icon">${icon}</span>${label}</button>`}
  function mobileNav(){return `<nav class="mobile-nav">${[['home','⌂','Home'],['decisions','▦','Decide'],['selections','✓','Selected'],['people','♙','People']].map(([p,i,l])=>`<button class="${route.page===p?'active':''}" data-action="nav" data-page="${p}"><span>${i}</span>${l}</button>`).join('')}</nav>`}
  function render(){if(!state||!user)return;document.title='The House Edit · '+state.project.name;let content=route.page==='home'?viewHome():route.page==='decisions'?viewDecisions():route.page==='decision'?viewDecision():route.page==='selections'?viewSelections():viewPeople();$('app').innerHTML=`<div class="shell">${sideNav()}<main class="main">${header()}${content}</main>${mobileNav()}</div>`;}
  function viewHome(){
    const all=state.decisions,approved=approvedDecisions(),awaiting=all.filter(needsMyVote);let roomCards=state.rooms.map(r=>{const rd=all.filter(d=>d.room_id===r.id),done=rd.filter(d=>d.status!=='open').length;return `<button class="room-card" data-action="room" data-id="${esc(r.id)}"><div class="room-visual ${roomClass(r)}">${roomIcon(r)}</div><div class="room-body"><strong>${esc(r.name)}</strong><div class="subtext">${rd.length} selections · ${done} approved</div><div class="meter"><span style="width:${rd.length?done/rd.length*100:0}%"></span></div></div></button>`}).join('');
    let short=(awaiting.length?awaiting:all.filter(d=>d.status==='open')).slice(0,4);
    return `<div class="page-head"><div><div class="eyebrow">WELCOME TO YOUR DESIGN STUDIO</div><h1>A home made of<br><i>good decisions.</i></h1><p>Capture inspiration, share opinions and make confident choices together — room by room.</p></div><div class="head-actions"><button class="btn primary" data-action="add-decision">＋ New decision</button></div></div><section class="hero"><div><div class="eyebrow">YOUR SHARED SPACE</div><h2>Every detail, thoughtfully chosen.</h2><p>Three perspectives, one cohesive home. Keep ideas and final decisions in one place.</p></div><button class="btn" data-action="nav" data-page="decisions">See all decisions →</button></section><section class="stat-grid"><div class="stat"><div class="num">${all.length}</div><div class="caption">Total decisions</div><div class="detail">Across ${state.rooms.length} rooms</div></div><div class="stat"><div class="num">${approved.length}</div><div class="caption">Approved selections</div><div class="detail">Ready to specify</div></div><div class="stat"><div class="num">${awaiting.length}</div><div class="caption">Need your opinion</div><div class="detail">Make your picks</div></div><div class="stat"><div class="num">${money(totalKnownPrice())}</div><div class="caption">Known selections total</div><div class="detail">Only listed item prices</div></div></section><section class="section"><div class="section-head"><h2>Explore by room</h2><button class="btn sm" data-action="add-room">＋ Add room</button></div><div class="room-grid">${roomCards}</div></section><section class="section"><div class="section-head"><div><h2>${awaiting.length?'Waiting for your vote':'On the drawing board'}</h2><p class="subtext">See what needs your attention next.</p></div><button class="btn sm" data-action="nav" data-page="decisions">All decisions →</button></div>${short.length?`<div class="decision-list">${short.map(decisionCard).join('')}</div>`:'<div class="empty"><div class="emoji">✳</div>Nothing pending — add a new design decision.</div>'}</section>`;
  }
  function decisionCard(dec){const opts=optionOf(dec),room=roomOf(dec),hasVoted=opts.some(o=>getVote(o.id,user.id));return `<article class="decision-card"><div class="decision-preview">${(opts.length?opts.slice(0,3):[{title:'Add ideas'}]).map(o=>imageMarkup(o)).join('')}</div><div class="decision-info"><div class="decision-meta">${esc(room?.name||'Room')} · ${opts.length} option${opts.length===1?'':'s'}</div><h3>${esc(dec.title)}</h3><p class="subtext">${esc(dec.notes||'Compare the options and make a choice together.')}</p><div class="decision-foot"><div>${statusPill(dec)} ${dec.status==='open'&&opts.length?`<span class="tag ${hasVoted?'approved':'pending'}">${hasVoted?'You voted':'Vote needed'}</span>`:''}</div>${voteDots(dec)}</div><button class="btn sm soft" style="align-self:flex-start;margin-top:14px" data-action="decision" data-id="${esc(dec.id)}">${dec.status==='open'?'Review options':'View selection'} →</button></div></article>`}
  function viewDecisions(){let ds=state.decisions.filter(d=>(route.room==='all'||d.room_id===route.room)&&(route.filter==='all'||(route.filter==='open'&&d.status==='open')||(route.filter==='approved'&&d.status!=='open')||(route.filter==='mine'&&needsMyVote(d)))&&(!route.search||(d.title+' '+d.notes+' '+(roomOf(d)?.name||'')).toLowerCase().includes(route.search.toLowerCase())));ds.sort((a,b)=> (a.status==='open'?0:1)-(b.status==='open'?0:1));const room=state.rooms.find(r=>r.id===route.room);return `<div class="page-head"><div><div class="eyebrow">OUR DESIGN DECISIONS</div><h1>${room?esc(room.name):'Every choice, in one place.'}</h1><p>Compare materials, fittings and furnishings — then get everyone on the same page.</p></div><div class="head-actions"><button class="btn primary" data-action="add-decision">＋ New decision</button></div></div><div class="toolbar"><label class="search">⌕ <input id="decision-search" placeholder="Search selections..." value="${esc(route.search)}" aria-label="Search decisions" /></label><select id="room-filter" class="select" aria-label="Filter by room"><option value="all">All rooms</option>${state.rooms.map(r=>`<option value="${esc(r.id)}" ${route.room===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select></div><div class="chip-group" style="margin-bottom:18px">${[['all','All'],['mine','Need my vote'],['open','Under review'],['approved','Approved']].map(([v,l])=>`<button class="chip ${route.filter===v?'active':''}" data-action="filter" data-filter="${v}">${l}</button>`).join('')}</div>${ds.length?`<div class="decision-list">${ds.map(decisionCard).join('')}</div>`:`<div class="empty"><div class="emoji">✳</div>No decisions match this view.<br><button class="btn sm soft" style="margin-top:12px" data-action="add-decision">Create a decision</button></div>`}`}
  function optionCard(opt,dec){const yourVote=getVote(opt.id,user.id),agreed=optionAgreement(opt),winning=dec.winner_option_id===opt.id;const votes=state.members.map(m=>{let choice=getVote(opt.id,m.user_id);return `<div class="person-vote"><span class="mini-avatar" style="background:${color(m.role)}">${esc(initials(m.display_name))}</span><span class="person-name">${esc(m.display_name)} ${m.user_id===user.id?'(you)':''}</span><strong>${choice?esc(VOTE_TEXT[choice]):'— Not voted'}</strong></div>`}).join('');const comments=state.comments.filter(c=>c.option_id===opt.id).sort((a,b)=>new Date(a.created_at)-new Date(b.created_at));return `<article class="option-card"><div class="option-media">${imageMarkup(opt,'option-visual')} ${winning?'<span class="badge-corner">✓ CHOSEN</span>':agreed?'<span class="badge-corner">✓ Both homeowners agree</span>':''}</div><div class="option-content"><div class="tiny">DESIGN OPTION</div><h3>${esc(opt.title)}</h3>${opt.price!==null&&opt.price!==undefined&&opt.price!==''?`<div class="price">${money(opt.price)}</div>`:''}<p class="option-notes">${esc(opt.notes||'No notes added yet.')}</p><div class="option-actions">${[['love','♥ Love'],['maybe','◒ Maybe'],['pass','✕ Pass']].map(([v,l])=>`<button class="votebtn ${yourVote===v?'active '+v:''}" data-action="vote" data-option="${esc(opt.id)}" data-vote="${v}" ${dec.status!=='open'?'disabled':''}>${l}</button>`).join('')}</div>${agreed?'<span class="tag approved">✓ Homeowner agreement</span>':optionDisagree(opt)?'<span class="tag disagree">⚑ Different opinions</span>':''}<div class="vote-rows">${votes}</div><section class="comments"><div class="tiny">Discussion · ${comments.length}</div>${comments.map(c=>{const m=memberOf(c.user_id);return `<div class="comment"><span class="mini-avatar" style="background:${color(m.role)}">${esc(initials(m.display_name))}</span><div class="comment-body"><strong>${esc(m.display_name)}</strong><span>${esc(timeAgo(c.created_at))}</span><p>${esc(c.body)}</p></div></div>`}).join('')}<form class="comment-field" data-form="comment" data-option="${esc(opt.id)}"><input name="body" placeholder="Add a thought or question..." maxlength="600" required aria-label="Write a comment"><button class="btn sm soft" type="submit">Send</button></form></section><div class="option-tools">${cleanUrl(opt.source_url)?`<a class="btn sm" href="${esc(cleanUrl(opt.source_url))}" target="_blank" rel="noopener noreferrer">↗ View supplier</a>`:''}${dec.status==='open'&&['owner','partner'].includes(user.role)?`<button class="btn sm ${agreed?'primary':'soft'}" data-action="approve" data-option="${esc(opt.id)}" ${!agreed?'disabled title="Both homeowners must vote Love or Maybe on this option"':''}>✓ Approve this</button>`:''}</div></div></article>`}
  function viewDecision(){const d=state.decisions.find(x=>x.id===route.decision);if(!d){route.page='decisions';return viewDecisions()}const room=roomOf(d),opts=optionOf(d),winner=state.options.find(o=>o.id===d.winner_option_id);const homeownerCount=homeowners().length;let banner='';if(d.status==='open'){
    const hasAgree=opts.some(optionAgreement);banner=homeownerCount<2?'<div class="notice warn">Invite your other homeowner so you can make decisions together. Approval requires both homeowner votes.</div>':hasAgree?'<div class="notice">✓ You both have a positive vote on at least one option. A homeowner can approve the final choice.</div>':'<div class="notice">♡ Vote on each option. Your designer friend can advise, and both homeowners must like a choice before it is approved.</div>';
  }else{banner=`<div class="notice">✓ Your selected option is <strong>${esc(winner?.title||'your saved selection')}</strong>. Status: ${esc(d.status)}.</div>`}
    const homeowner=['owner','partner'].includes(user.role);
    return `<button class="back" data-action="room" data-id="${esc(room?.id||'all')}">← Back to ${esc(room?.name||'decisions')}</button><div class="detail-header"><div><div class="eyebrow">${esc(room?.name||'YOUR HOME')} / SELECTION BOARD</div><h1>${esc(d.title)}</h1><p class="detail-intro">${esc(d.notes||'Find something you all love.')}</p><div style="margin-top:12px">${statusPill(d)} <span class="tag open">${opts.length} options</span></div></div><div class="head-actions">${d.status==='open'?`<button class="btn primary" data-action="add-option" data-id="${esc(d.id)}">＋ Add an option</button>`:''}${homeowner&&d.status!=='open'?`<button class="btn" data-action="reopen" data-id="${esc(d.id)}">↶ Reopen</button>`:''}</div></div>${banner}${opts.length?`<div class="option-grid">${opts.map(o=>optionCard(o,d)).join('')}</div>`:`<div class="empty"><div class="emoji">🖼</div><strong>Every great choice starts with an idea.</strong><p>Add a product, upload a picture or paste a link.</p><button class="btn primary" style="margin-top:15px" data-action="add-option" data-id="${esc(d.id)}">＋ Add the first option</button></div>`}${d.status==='open'&&opts.length?`<div style="margin-top:18px"><button class="btn soft" data-action="add-option" data-id="${esc(d.id)}">＋ Another option</button></div>`:''}${d.status!=='open'&&homeowner?`<div class="floating"><div class="final-bar"><div><strong>✓ ${esc(winner?.title||'Selection')} — ${esc(d.status)}</strong><p>Move this decision along as purchasing and installation progress.</p></div><div class="head-actions">${d.status==='approved'?`<button class="btn primary" data-action="advance" data-id="${esc(d.id)}" data-status="ordered">Mark ordered →</button>`:d.status==='ordered'?`<button class="btn primary" data-action="advance" data-id="${esc(d.id)}" data-status="installed">Mark installed →</button>`:''}</div></div></div>`:''}`}
  function viewSelections(){const ds=approvedDecisions();const total=totalKnownPrice();return `<div class="page-head"><div><div class="eyebrow">FINAL SELECTIONS REGISTER</div><h1>Chosen for our home.</h1><p>Everything you've agreed on, with product links and ordering status in one dependable place.</p></div><div class="head-actions"><button class="btn" data-action="export">↓ Export CSV</button></div></div><div class="stat-grid three"><div class="stat"><div class="num">${ds.length}</div><div class="caption">Selections approved</div></div><div class="stat"><div class="num">${ds.filter(d=>d.status==='ordered').length}</div><div class="caption">Ordered</div></div><div class="stat"><div class="num">${money(total)}</div><div class="caption">Total of entered prices</div></div></div><section class="section"><div class="section-head"><h2>Selection schedule</h2><span class="subtext">Grouped by room</span></div>${ds.length?state.rooms.map(room=>{const rows=ds.filter(d=>d.room_id===room.id);return rows.length?`<h3 style="margin:22px 0 8px">${roomIcon(room)} ${esc(room.name)}</h3>${rows.map(d=>{const o=state.options.find(o=>o.id===d.winner_option_id);return `<div class="selection-row">${imageMarkup(o||{title:'Selection'})}<div class="selection-body"><strong>${esc(d.title)}</strong><div>${esc(o?.title||'Selection')}</div><small>${esc(o?.notes||'')}${o?.price!==null&&o?.price!==undefined?' · '+money(o.price):''}</small></div>${statusPill(d)}<button class="btn sm" data-action="decision" data-id="${esc(d.id)}">Open ↗</button></div>`}).join('')}`:''}).join(''):`<div class="empty"><div class="emoji">✓</div>Your approved decisions will appear here.</div>`}</section><div class="block-note">Prices are manually entered, in Australian dollars. This is a selections tracker, not a quote or tax calculation.</div>`}
  function viewPeople(){const members=state.members;return `<div class="page-head"><div><div class="eyebrow">THE PEOPLE BEHIND THE HOME</div><h1>Better together.</h1><p>Both homeowners make the final call. Your designer friend can suggest options, vote and leave professional feedback.</p></div></div><div class="members-grid">${[['owner','Homeowner','Can add, vote and approve'],['partner','Homeowner','Can add, vote and approve'],['designer','Design adviser','Can suggest, vote and comment']].map(([role,title,detail])=>{const m=members.find(x=>x.role===role);return `<div class="member-card"><div class="avatar" style="background:${color(role)}">${m?esc(initials(m.display_name)):'+'}</div><h4>${esc(m?.display_name||'Not joined yet')}</h4><div class="subtext">${title}</div><p style="font-size:12px;color:var(--ink2);margin-top:12px">${detail}</p></div>`}).join('')}</div>${mode==='demo'?`<section class="section"><div class="invite-panel"><h3>Try all three perspectives</h3><p class="subtext" style="margin:9px 0">Change the preview person in the sidebar to test how individual votes affect each decision. Demo changes are only saved in this browser.</p><select class="select" id="people-persona">${state.members.map(m=>`<option value="${esc(m.user_id)}" ${m.user_id===user.id?'selected':''}>${esc(m.display_name)}</option>`).join('')}</select></div></section>`:`<section class="section"><h2>Private invitations</h2><p class="subtext">Share the correct code with each person. Each invitation can be used once, by the person joining with their email.</p>${user.role==='owner'?(state.invites||[]).map(inv=>`<div class="invite-panel"><div class="tiny">${inv.role==='partner'?'YOUR OTHER HOMEOWNER':'DESIGNER FRIEND'}</div><span class="invite-code">${inv.used_by?'Already joined':esc(inv.code)}</span>${inv.used_by?'<span class="tag approved">Invitation claimed</span>':`<button class="btn sm soft" data-action="copy" data-code="${esc(inv.code)}">Copy code</button>`}</div>`).join(''):'<div class="invite-panel">Only the project owner can view invitation codes.</div>'}</section><section class="section"><button class="btn" data-action="signout">Sign out of account</button></section>`}`}
  function toast(s){const el=$('toast');if(!el)return;el.textContent=s;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3400)}
  function modal(title,body,submitLabel='Save'){ $('modal-root').innerHTML=`<div class="modal-overlay" id="overlay"><div class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${esc(title)}</h2><button class="btn icononly" data-action="close-modal" aria-label="Close">✕</button></div>${body}</div></div>`;}
  function closeModal(){++lookupRun;clearTimeout(lookupTimeout);$('modal-root').innerHTML=''}
  function askNewRoom(){modal('Add a room',`<form data-form="room"><div class="formline"><label>Room name</label><input name="name" placeholder="e.g. Dining Room" maxlength="60" required autofocus></div><div class="formline"><label>Room icon</label><select name="emoji">${['🏠','🍽️','🛋️','🛁','🛏️','🌿','🚪','💡','🪑','🧱'].map(e=>`<option>${e}</option>`).join('')}</select></div><div class="modal-foot"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn primary" type="submit">Add room</button></div></form>`)}
  function askNewDecision(){modal('New design decision',`<p class="prompt-note">What's something you want the group to choose together?</p><form data-form="decision"><div class="formline"><label>Decision title</label><input name="title" placeholder="e.g. Laundry floor tiles" maxlength="110" required autofocus></div><div class="formline"><label>Which room?</label><select name="room_id" required>${state.rooms.map(r=>`<option value="${esc(r.id)}" ${route.room===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select></div><div class="formline"><label>Notes (optional)</label><textarea name="notes" maxlength="650" placeholder="Dimensions, preferences, budget or any must-haves..."></textarea></div><div class="modal-foot"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn primary" type="submit">Create decision</button></div></form>`)}
  function askNewOption(decId){const d=state.decisions.find(d=>d.id===decId);if(!d)return;modal('Add an option',`<p class="prompt-note">For: ${esc(d.title)}. Paste a product link to find its image and name automatically.</p><form data-form="option" data-decision="${esc(decId)}"><div class="formline"><label>Product / supplier link</label><input name="source_url" type="text" inputmode="url" spellcheck="false" placeholder="Paste product link (https://… or www.… )" autocomplete="url" autofocus><small class="field-hint">Paste a product-page link and the image and name will fill in automatically. Some shops block third-party previews.</small></div><div class="product-lookup" id="product-lookup" aria-live="polite"><div class="product-lookup-placeholder"><span class="product-lookup-symbol">↗</span><div><strong>Product preview</strong><small>Paste a link to load an image and product details.</small></div></div></div><div class="formline"><label>Option name</label><input name="title" placeholder="Automatically filled from the link, or type a name" maxlength="110"></div><div class="form-grid"><div class="formline"><label>Price (AUD, optional)</label><input name="price" type="number" min="0" step="0.01" placeholder="e.g. 229.00"></div><div class="formline"><label>Upload your own photo (optional)</label><input name="photo" type="file" accept="image/jpeg,image/png,image/webp"></div></div><div class="formline"><label>Or paste a direct image URL (optional)</label><input name="image_url" type="url" placeholder="https://.../product.jpg"><small class="field-hint">An uploaded photo or direct image URL takes priority over the product link.</small></div><div class="formline"><label>Notes</label><textarea name="notes" maxlength="650" placeholder="What do you like about it? Size, colour, finish..."></textarea></div><p class="prompt-note">A public link-preview service reads the product page. If a shop blocks it, you can still save the link and add a photo later. Verify prices before ordering.</p><div class="modal-foot"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn primary" type="submit">Add to comparison</button></div></form>`)}

  // An HTML-only static site cannot read other shops' HTML in the browser because of CORS.
  // Microlink resolves publicly available page metadata. Cache avoids repeated requests on paste/save.
  const productCache=new Map();
  let lookupTimeout=null, lookupRun=0;
  function normalizeSource(value){
    let v=String(value||'').trim();
    if(v && !/^[a-z][a-z0-9+.-]*:\/\//i.test(v) && /^[\w-]+\.[\w.-]+/.test(v))v='https://'+v;
    return cleanUrl(v);
  }
  function isImageLink(url){return /\.(?:jpe?g|png|webp)(?:$|[?#])/i.test(url);}
  function lookupMessage(message,level='info'){
    const panel=$('product-lookup');if(!panel)return;
    panel.dataset.status=level;
    const activeUrl=panel.closest('form')?.elements.source_url.value?.trim();
    panel.innerHTML=`<div class="product-lookup-placeholder"><span class="product-lookup-symbol">${level==='pending'?'◌':level==='success'?'✓':'↗'}</span><div><strong>${level==='pending'?'Finding the product…':level==='success'?'Product photo ready':level==='warn'?'Automatic preview unavailable':'Product preview'}</strong><small>${esc(message)}</small>${level==='warn'&&activeUrl?'<button class="btn sm ghost retry-product" type="button" data-action="retry-product">↻ Try again</button>':''}</div></div>`;
  }
  function showProductPreview(data){
    const panel=$('product-lookup');if(!panel)return;
    if(!data.image_url){lookupMessage('The link did not provide a photo. You can save the product link and name, or add a photo yourself.','warn');return;}
    const img=photoTag(data.image_url,data.source_url,'Photo of '+(data.title||'product'),'data-product-preview="true"');
    panel.dataset.status='pending';
    panel.innerHTML=`<div class="product-lookup-result"><div class="product-lookup-thumb">${img}</div><div><strong>${esc(data.title||'Product image')}</strong><small class="photo-status">Checking that the retailer photo displays…</small></div></div>`;
    const preview=panel.querySelector('img');
    if(preview)preview.addEventListener('load',()=>{if(!preview.isConnected)return;panel.dataset.status='success';const line=panel.querySelector('.photo-status');if(line)line.textContent='Photo ready. It will be saved with this option.';});
  }
  function titleFromUrl(url){
    try{
      const link=new URL(url),parts=link.pathname.split('/').filter(Boolean);
      const slug=decodeURIComponent(parts.at(-1)||link.hostname.replace(/^www\./,''));
      return slug.replace(/\.(?:html?|php)$/i,'').replace(/[-_]+/g,' ').replace(/\s+/g,' ').trim().slice(0,110);
    }catch{return '';}
  }
  async function fetchProductData(url){
    const source=normalizeSource(url);
    if(!source)throw new Error('Paste a valid product-page link (for example, https://shop.com.au/product).');
    if(isImageLink(source))return {title:titleFromUrl(source),image_url:source,source_url:source};
    if(!productCache.has(source)){
      const promise=(async()=>{
        const controller=new AbortController();
        const timeout=setTimeout(()=>controller.abort(),20000);
        try{
          const response=await fetch('https://api.microlink.io?url='+encodeURIComponent(source),{signal:controller.signal});
          let body={};try{body=await response.json()}catch{}
          if(!response.ok||body.status!=='success'){
            const code=String(body.code||'');
            if(response.status===429||code==='ERATE')throw new Error('The free product-preview limit has been reached for today. Add a photo manually, or retry tomorrow.');
            if(code==='EPROXYNEEDED'||code==='EPROXY')throw new Error('This retailer blocks automatic product previews. You can still save the link and upload a photo.');
            if(code==='EBRWSRTIMEOUT'||code==='ETIMEOUT')throw new Error('This retailer took too long to respond. Try again, or add a photo manually.');
            throw new Error('The product page could not be read by the preview service. You can still add it manually.');
          }
          const meta=body.data||{};
          const name=String(meta.title||'').replace(/\s*[|–—]\s*[^|–—]+$/, '').trim().slice(0,110);
          if(/^(?:just a moment|access denied|403 forbidden|attention required|please enable javascript|one moment)/i.test(name))throw new Error('The retailer returned a security-check page instead of a product. Upload a photo if you need one.');
          return {title:name||titleFromUrl(source),image_url:cleanUrl(typeof meta.image==='string'?meta.image:meta.image?.url),source_url:source};
        }catch(err){
          if(err.name==='AbortError')throw new Error('The product preview timed out. Try again or upload a photo.');
          if(err instanceof TypeError)throw new Error('Could not contact the link-preview service. Check your connection or try again.');
          throw err;
        }finally{clearTimeout(timeout)}
      })();
      productCache.set(source,promise);
      promise.catch(()=>productCache.delete(source));
    }
    return productCache.get(source);
  }
  async function lookupProduct(form,rawUrl){
    const run=++lookupRun,source=normalizeSource(rawUrl);
    if(!form?.isConnected)return;
    if(!source){lookupMessage('Paste a product link to see its photo.');return;}
    if(!['http:','https:'].includes(new URL(source).protocol))return;
    lookupMessage('Looking up the product name and photo…','pending');
    try{
      const data=await fetchProductData(source);
      if(run!==lookupRun||!form.isConnected||normalizeSource(form.elements.source_url.value)!==source)return;
      form.dataset.lookupUrl=source;
      form.dataset.lookupImage=data.image_url||'';
      const name=form.elements.title;
      if(data.title && (!name.value.trim() || name.value===name.dataset.autoTitle)){
        name.value=data.title;name.dataset.autoTitle=data.title;
      }
      // Respect a manually provided image; otherwise preview the extracted photo.
      if(form.elements.photo.files?.length){lookupMessage('Your uploaded photo will be used.','success');return;}
      const custom=cleanUrl(form.elements.image_url.value);
      showProductPreview({...data,image_url:custom||data.image_url,source_url:custom?'':source});
    }catch(err){
      if(run!==lookupRun||!form.isConnected)return;
      form.dataset.lookupUrl=source;form.dataset.lookupImage='';
      const name=form.elements.title;if(!name.value.trim())name.value=titleFromUrl(source);
      lookupMessage(err.message||'Product image unavailable. You can add a photo manually.','warn');
    }
  }
  function queueProductLookup(form){
    clearTimeout(lookupTimeout);
    const input=form.elements.source_url,source=normalizeSource(input.value);
    if(!input.value.trim()){++lookupRun;form.dataset.lookupImage='';form.dataset.lookupUrl='';lookupMessage('Paste a product link to see its photo.');return;}
    if(!source){++lookupRun;form.dataset.lookupImage='';form.dataset.lookupUrl='';lookupMessage('Enter a valid product link.','warn');return;}
    lookupTimeout=setTimeout(()=>lookupProduct(form,source),450);
  }
  function refreshPreviewFromOverrides(form){
    const uploaded=form.elements.photo.files?.length;
    if(uploaded){lookupMessage('Your uploaded photo takes priority over the website image.','success');return;}
    const custom=cleanUrl(form.elements.image_url.value);
    if(custom){showProductPreview({title:'Your chosen image',image_url:custom,source_url:''});return;}
    if(form.dataset.lookupImage){showProductPreview({title:form.elements.title.value,image_url:form.dataset.lookupImage,source_url:form.dataset.lookupUrl});return;}
    if(form.elements.source_url.value.trim())queueProductLookup(form);
    else lookupMessage('Paste a product link to see its photo.');
  }
  function showAuth(){const logged=client?!!user:false;$('app').innerHTML=`<div class="auth-shell"><div class="auth-card"><div class="logo"><span class="logo-emblem">✳</span><span>the house edit<i>.</i></span></div><div class="eyebrow">A HOME THAT FEELS LIKE YOU</div><h1>${logged?'Your shared home.':'Let’s create your home.'}</h1><p>${logged?'Start your home project, or join one using the private code you received.':'Sign in using an email link so your decisions sync securely across all three devices.'}</p>${!logged?`<form data-form="signin"><div class="formline"><label>Email address</label><input name="email" type="email" placeholder="you@example.com" required autocomplete="email"></div><button class="btn primary" type="submit">Email me a sign-in link →</button></form><div class="help">Check spam if the link doesn’t arrive. Return to this page after signing in.</div>`:`<form data-form="create-project"><h3>Start a new home</h3><div class="formline"><label>Project name</label><input name="name" value="Our Home" maxlength="80" required></div><div class="formline"><label>Your name</label><input name="display_name" placeholder="Your name" maxlength="60" required></div><button class="btn primary" type="submit">Create our home</button></form><div class="divider" style="margin:25px 0"></div><form data-form="join-project"><h3>Join an existing home</h3><div class="formline"><label>Your name</label><input name="display_name" maxlength="60" required placeholder="Your name"></div><div class="formline"><label>Invitation code</label><input name="code" maxlength="30" required placeholder="Paste your private code"></div><button class="btn soft" type="submit">Join the shared project</button></form><button class="btn ghost sm" style="margin-top:16px" data-action="signout">Sign out</button>`}</div></div>`}
  async function cloudInit(){if(!window.supabase){alert('Could not load the Supabase library. Check your connection, then reload.');initDemo();return}mode='cloud';client=window.supabase.createClient(cfg.supabaseUrl,cfg.supabasePublishableKey);const {data:{user:u}}=await client.auth.getUser();if(!u){user=null;showAuth();return;}user={id:u.id,email:u.email||'',role:''};await cloudLoad();}
  async function cloudLoad(){if(!client||!user)return;try{
    const {data:ms,error:me}=await client.from('house_members').select('*').eq('user_id',user.id);if(me)throw me;
    if(!ms?.length){state=null;showAuth();return;}
    const self=ms[0],pid=self.project_id;user.role=self.role;
    const queries=[client.from('house_projects').select('*').eq('id',pid).single(),client.from('house_members').select('*').eq('project_id',pid),client.from('house_rooms').select('*').eq('project_id',pid).order('sort_order'),client.from('house_decisions').select('*').eq('project_id',pid).order('created_at',{ascending:false})];
    if(self.role==='owner')queries.push(client.from('house_invitations').select('*').eq('project_id',pid));
    const results=await Promise.all(queries);for(const r of results)if(r.error)throw r.error;
    const [pr,mm,rr,dd]=results;const dIds=dd.data.map(d=>d.id);
    let opts=[],votes=[],comments=[];
    if(dIds.length){const o=await client.from('house_options').select('*').in('decision_id',dIds);if(o.error)throw o.error;opts=o.data||[];const oIds=opts.map(x=>x.id);if(oIds.length){const [v,c]=await Promise.all([client.from('house_votes').select('*').in('option_id',oIds),client.from('house_comments').select('*').in('option_id',oIds).order('created_at')]);if(v.error)throw v.error;if(c.error)throw c.error;votes=v.data||[];comments=c.data||[];}}
    // Signed URLs let every authorised household member see private uploads.
    await Promise.all(opts.filter(o=>o.image_path).map(async o=>{const {data}=await client.storage.from('house-option-images').createSignedUrl(o.image_path,3600);o.display_url=data?.signedUrl||'';}));
    state={project:pr.data,members:mm.data,rooms:rr.data.map(r=>({...r,emoji:r.emoji||'🏡'})),decisions:dd.data,options:opts,votes,comments,invites:(results[4]?.data||[])};
    if(!state.decisions.find(d=>d.id===route.decision)&&route.page==='decision'){route.page='decisions';route.decision=null;}
    if(route.room!=='all'&&!state.rooms.find(r=>r.id===route.room))route.room='all';
    render();subscribe(pid);
  }catch(err){console.error(err);toast('Could not load project: '+(err.message||err));}}
  function subscribe(pid){if(channel)return;channel=client.channel('house-edit-'+pid);['house_rooms','house_decisions','house_options','house_votes','house_comments','house_members'].forEach(t=>channel.on('postgres_changes',{event:'*',schema:'public',table:t},()=>{clearTimeout(refreshTimer);refreshTimer=setTimeout(()=>cloudLoad(),400);}));channel.subscribe();}
  async function write(action){if(busy)return;busy=true;try {await action();if(mode==='demo')demoSave();else await cloudLoad();render();}catch(err){console.error(err);toast(err.message||'Unable to save change');}finally{busy=false}}
  async function addRoom(name,emoji){const obj={id:uuid(),project_id:state.project.id,name,emoji,sort_order:state.rooms.length};await write(async()=>{if(mode==='demo')state.rooms.push(obj);else{const {error}=await client.from('house_rooms').insert(obj);if(error)throw error;}closeModal();toast('Room added')});}
  async function addDecision(title,room_id,notes){const obj={id:uuid(),project_id:state.project.id,room_id,title,notes,status:'open',winner_option_id:null,created_at:new Date().toISOString()};await write(async()=>{if(mode==='demo')state.decisions.unshift(obj);else{const {error}=await client.from('house_decisions').insert({id:obj.id,project_id:obj.project_id,room_id,title,notes});if(error)throw error;}closeModal();route.page='decision';route.decision=obj.id;toast('Decision created')});}
  async function fileDataUrl(file){return new Promise((resolve,reject)=>{let fr=new FileReader();fr.onload=()=>resolve(fr.result);fr.onerror=reject;fr.readAsDataURL(file);});}
  async function addOption(decision_id,fields,file){await write(async()=>{let image_path='',image_url=cleanUrl(fields.image_url);
    // Last-chance lookup: pressing Save immediately after paste still extracts the image.
    if(!(file&&file.size) && !image_url && normalizeSource(fields.source_url)){
      try{const data=await fetchProductData(fields.source_url);image_url=data.image_url||'';if(!fields.title.trim())fields.title=data.title||'';}
      catch(err){console.info('Product link preview unavailable:',err.message);if(!fields.title.trim())fields.title=titleFromUrl(normalizeSource(fields.source_url));}
    }
    if(!fields.title.trim())fields.title=titleFromUrl(normalizeSource(fields.source_url));if(!fields.title.trim())throw new Error('Enter an option name to save this product.');if(file&&file.size){if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('Use a JPG, PNG or WebP image.');if(file.size>6*1024*1024)throw new Error('Maximum image size is 6 MB.');if(mode==='demo'){if(file.size>700*1024)throw new Error('Demo photo limit is 700 KB. Shared cloud uploads allow 6 MB.');image_url=await fileDataUrl(file);}else{const ext={'image/jpeg':'jpg','image/png':'png','image/webp':'webp'}[file.type];image_path=`${state.project.id}/${uuid()}.${ext}`;const {error}=await client.storage.from('house-option-images').upload(image_path,file,{contentType:file.type,upsert:false});if(error)throw error;}}
    const obj={id:uuid(),decision_id,title:fields.title,notes:fields.notes,source_url:cleanUrl(fields.source_url),price:fields.price===''?null:Number(fields.price),image_url,image_path,created_by:user.id,created_at:new Date().toISOString()};if(mode==='demo')state.options.push(obj);else{const {error}=await client.from('house_options').insert(obj);if(error)throw error;}closeModal();toast('Option added')});}
  async function vote(option_id,choice){const old=getVote(option_id,user.id);await write(async()=>{if(mode==='demo'){if(old){state.votes=state.votes.filter(v=>!(v.option_id===option_id&&v.user_id===user.id));}if(old!==choice)state.votes.push({option_id,user_id:user.id,choice});}else{const query=old===choice?client.from('house_votes').delete().match({option_id,user_id:user.id}):client.from('house_votes').upsert({option_id,user_id:user.id,choice},{onConflict:'option_id,user_id'});const {error}=await query;if(error)throw error;}toast(old===choice?'Vote removed':'Your opinion saved');});}
  async function comment(option_id,body){await write(async()=>{const o={id:uuid(),option_id,user_id:user.id,body,created_at:new Date().toISOString()};if(mode==='demo')state.comments.push(o);else{const {error}=await client.from('house_comments').insert(o);if(error)throw error;}toast('Comment shared')});}
  async function approve(option_id){const opt=state.options.find(o=>o.id===option_id),dec=state.decisions.find(d=>d.id===opt?.decision_id);if(!opt||!dec)return;if(!['owner','partner'].includes(user.role)){toast('Only homeowners can approve.');return;}if(!optionAgreement(opt)){toast('Both homeowners must vote Love or Maybe first.');return;}if(!confirm(`Approve “${opt.title}” as the final selection?`))return;await write(async()=>{if(mode==='demo'){dec.status='approved';dec.winner_option_id=option_id;}else{const {error}=await client.rpc('house_approve_option',{p_option_id:option_id});if(error)throw error;}toast('Selection approved ✓')});}
  async function changeStatus(decision_id,status){if(!['owner','partner'].includes(user.role))return;await write(async()=>{if(mode==='demo'){const d=state.decisions.find(d=>d.id===decision_id);d.status=status;if(status==='open')d.winner_option_id=null;}else{const {error}=await client.rpc('house_set_status',{p_decision_id:decision_id,p_status:status});if(error)throw error;}toast(status==='open'?'Decision reopened':'Selection marked '+status)});}
  function csvExport(){const rows=[['Room','Decision','Selected option','Price AUD','Status','Supplier URL','Notes']];for(const d of approvedDecisions()){const o=state.options.find(o=>o.id===d.winner_option_id);rows.push([roomOf(d)?.name||'',d.title,o?.title||'',o?.price??'',d.status,o?.source_url||'',o?.notes||'']);}const csv='\ufeff'+rows.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='the-house-edit-selections.csv';a.click();URL.revokeObjectURL(url);toast('Selections CSV exported');}
  function go(page,room){route.page=page;if(room!==undefined)route.room=room;route.search='';route.filter='all';route.decision=null;render();window.scrollTo({top:0,behavior:'smooth'});}
  function changePersona(id){if(mode!=='demo'||!state.members.some(m=>m.user_id===id))return;localStorage.setItem('the-house-edit-persona',id);user={id,role:memberOf(id).role};render();toast('Now previewing '+memberOf(id).display_name)}
  // A failed image must never silently stay broken. This handles saved cards and
  // live previews, including previously imported retailer images.
  document.addEventListener('error',ev=>{
    const img=ev.target;
    if(!(img instanceof HTMLImageElement)||!img.hasAttribute('data-image-fallbacks'))return;
    let rest=[];try{rest=JSON.parse(img.dataset.imageFallbacks||'[]')}catch{}
    if(rest.length){img.dataset.imageFallbacks=JSON.stringify(rest.slice(1));img.src=rest[0];return;}
    img.removeAttribute('data-image-fallbacks');img.style.display='none';
    if(img.dataset.productPreview){lookupMessage('The retailer photo is unavailable, including through image relays. You can save the product link and add a photo manually.','warn');}
    else if(img.nextElementSibling)img.nextElementSibling.style.display='grid';
  },true);
  document.addEventListener('change',ev=>{if(ev.target.id==='demo-persona'||ev.target.id==='people-persona')changePersona(ev.target.value);if(ev.target.id==='room-filter'){route.room=ev.target.value;render()}const f=ev.target.closest('form[data-form="option"]');if(f){if(ev.target.name==='source_url')queueProductLookup(f);if(['photo','image_url'].includes(ev.target.name))refreshPreviewFromOverrides(f)}});
  document.addEventListener('input',ev=>{const optForm=ev.target.closest('form[data-form="option"]');if(optForm){if(ev.target.name==='source_url')queueProductLookup(optForm);if(ev.target.name==='image_url')refreshPreviewFromOverrides(optForm);}if(ev.target.id==='decision-search'){const sel=ev.target.selectionStart;route.search=ev.target.value;const html=viewDecisions();const holder=document.createElement('div');holder.innerHTML=html;const list=holder.querySelector('.decision-list')||holder.querySelector('.empty');const existing=document.querySelector('.decision-list')||document.querySelector('.empty');if(existing&&list){existing.replaceWith(list);}else{render();const input=$('decision-search');input.focus();input.setSelectionRange(sel,sel);}}});
  document.addEventListener('click',async ev=>{const button=ev.target.closest('[data-action]');if(!button)return;const a=button.dataset.action,id=button.dataset.id;try{switch(a){case 'nav':go(button.dataset.page);break;case 'room':go('decisions',id);break;case 'filter':route.filter=button.dataset.filter;render();break;case 'decision':route.page='decision';route.decision=id;render();window.scrollTo(0,0);break;case 'add-room':askNewRoom();break;case 'add-decision':askNewDecision();break;case 'add-option':askNewOption(id);break;case 'retry-product':{const form=button.closest('form[data-form="option"]');if(form){const source=normalizeSource(form.elements.source_url.value);if(source)productCache.delete(source);lookupProduct(form,source);}break;}case 'close-modal':closeModal();break;case 'vote':await vote(button.dataset.option,button.dataset.vote);break;case 'approve':await approve(button.dataset.option);break;case 'reopen':await changeStatus(id,'open');break;case 'advance':await changeStatus(id,button.dataset.status);break;case 'export':csvExport();break;case 'reset-demo':resetDemo();break;case 'copy':await navigator.clipboard.writeText(button.dataset.code);toast('Private invitation code copied');break;case 'refresh':if(mode==='cloud')await cloudLoad();else render();toast('Up to date');break;case 'signout':await client.auth.signOut();user=null;state=null;if(channel){await client.removeChannel(channel);channel=null;}showAuth();break;}}catch(e){console.error(e);toast(e.message||'Something went wrong')}});
  document.addEventListener('submit',async ev=>{const form=ev.target.closest('form[data-form]');if(!form)return;ev.preventDefault();if(busy)return;const data=new FormData(form),action=form.dataset.form;try{switch(action){case 'room':await addRoom(String(data.get('name')||'').trim(),String(data.get('emoji')||'🏡'));break;case 'decision':await addDecision(String(data.get('title')||'').trim(),data.get('room_id'),String(data.get('notes')||'').trim());break;case 'option':await addOption(form.dataset.decision,{title:String(data.get('title')||'').trim(),price:String(data.get('price')||''),notes:String(data.get('notes')||'').trim(),source_url:normalizeSource(String(data.get('source_url')||'')),image_url:String(data.get('image_url')||'')},data.get('photo'));break;case 'comment':{const body=String(data.get('body')||'').trim();if(body)await comment(form.dataset.option,body);break;}case 'signin':{busy=true;const {error}=await client.auth.signInWithOtp({email:String(data.get('email')).trim(),options:{emailRedirectTo:window.location.origin+window.location.pathname}});if(error)throw error;toast('Check your email for your sign-in link');showAuth();break;}case 'create-project':{busy=true;const {error}=await client.rpc('house_create_project',{p_name:String(data.get('name')).trim(),p_display_name:String(data.get('display_name')).trim()});if(error)throw error;await cloudLoad();toast('Your home is ready');break;}case 'join-project':{busy=true;const {error}=await client.rpc('house_join_project',{p_invitation_code:String(data.get('code')).trim(),p_display_name:String(data.get('display_name')).trim()});if(error)throw error;await cloudLoad();toast('You joined the home');break;}}}catch(error){console.error(error);toast(error.message||'Unable to complete action')}finally{busy=false}});
  document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
  document.addEventListener('click',ev=>{if(ev.target.id==='overlay')closeModal()});
  if(cloudConfigured)cloudInit();else initDemo();
})();
